import json

# Try identifying connected components of non-9 cells (using 8-connectivity)
test_input = [
    [6, 8, 9, 6, 9, 9],
    [9, 9, 9, 9, 9, 9],
    [9, 8, 9, 9, 2, 9],
    [8, 9, 9, 9, 9, 9],
    [8, 9, 9, 9, 9, 9],
    [9, 1, 9, 9, 9, 9],
    [8, 9, 9, 8, 9, 9],
    [9, 9, 9, 9, 9, 6],
    [6, 9, 9, 1, 9, 9],
    [9, 9, 9, 9, 8, 9]
]

def find_components(grid):
    visited = set()
    components = []

    def dfs(r, c):
        if (r, c) in visited or r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]):
            return
        visited.add((r, c))
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                dfs(r + dr, c + dc)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 9 and (r, c) not in visited:
                comp = []
                dfs(r, c)
                comp.append(sorted(visited))
                visited.discard((r, c))  # Remove from visited for component tracking
                components.append(comp)

    return components

components = find_components(test_input)
print(f"Number of connected components: {len(components)}")
for i, comp in enumerate(components):
    print(f"Component {i}: {comp}")

# Maybe mark each component with a unique ID?
output = [[0]*6 for _ in range(10)]
component_id = {}
for idx, comp in enumerate(components):
    for r, c in comp:
        output[r][c] = idx + 1  # 1-indexed IDs

print(json.dumps({"action": "submit", "grid": output}))

